-- 1. Limpar dados primeiro (remove OK/PENDENTE antigos)
UPDATE public.frotas_rastreadores SET infleet = NULL, updated_at = now();

-- 2. Trocar constraint (sem dados conflitantes)
ALTER TABLE public.frotas_rastreadores DROP CONSTRAINT IF EXISTS frotas_rastreadores_infleet_check;
ALTER TABLE public.frotas_rastreadores
  ADD CONSTRAINT frotas_rastreadores_infleet_check
  CHECK (infleet IN ('PENDENTE','RETIRADO'));

-- 3. Planilha = PENDENTE (123 registros ativos no Infleet)
